$AB = CD$ and $\angle AOB = 84^{\circ}$.
Find $\angle COD$.
[tikz]\begin{tikzpicture}[every node/.style={font=\large}]
\usetikzlibrary{calc, decorations.markings, angles, quotes}
\usetikzlibrary{decorations.markings}
\tikzset{
  tickmark/.style={postaction={decorate, decoration={markings,
    mark=at position 0.5 with {\draw[black] (0pt,-4pt) -- (0pt,4pt);}}}},
  tickmark2/.style={postaction={decorate, decoration={markings,
    mark=at position 0.5 with {\draw[black] (-2pt,-4pt) -- (-2pt,4pt);
                               \draw[black] (2pt,-4pt) -- (2pt,4pt);}}}},
  tickmark3/.style={postaction={decorate, decoration={markings,
    mark=at position 0.5 with {\draw[black] (-3pt,-4pt) -- (-3pt,4pt);
                               \draw[black] (0pt,-4pt) -- (0pt,4pt);
                               \draw[black] (3pt,-4pt) -- (3pt,4pt);}}}},
}
\coordinate (O) at (0,0);
\draw (O) circle (2);
\fill (O) circle (1.5pt) node[left] {$O$};
\coordinate (A) at (-1.286,1.532);
\coordinate (B) at (1.389,1.439);
\coordinate (C) at (1.286,-1.532);
\coordinate (D) at (-1.389,-1.439);
\node[above left] at (A) {$A$};
\node[above right] at (B) {$B$};
\node[below right] at (C) {$C$};
\node[below left] at (D) {$D$};
\draw[tickmark] (A) -- (B);
\draw[tickmark] (C) -- (D);
\draw (O) -- (A);
\draw (O) -- (B);
\draw (O) -- (C);
\draw (O) -- (D);
\pic[draw, "$84^{\circ}$", angle radius=0.55cm, angle eccentricity=2] {angle = B--O--A};
\pic[draw, "$x$", angle radius=0.55cm, angle eccentricity=2] {angle = D--O--C};
\end{tikzpicture}
[/tikz]

$AB = CD$, $OE \perp AB$, $OF \perp CD$, and $OF = 5.4$ cm.
Find $OE$.
[tikz]\begin{tikzpicture}[every node/.style={font=\large}]
\usetikzlibrary{calc, decorations.markings, angles, quotes}
\usetikzlibrary{decorations.markings}
\tikzset{
  tickmark/.style={postaction={decorate, decoration={markings,
    mark=at position 0.5 with {\draw[black] (0pt,-4pt) -- (0pt,4pt);}}}},
  tickmark2/.style={postaction={decorate, decoration={markings,
    mark=at position 0.5 with {\draw[black] (-2pt,-4pt) -- (-2pt,4pt);
                               \draw[black] (2pt,-4pt) -- (2pt,4pt);}}}},
  tickmark3/.style={postaction={decorate, decoration={markings,
    mark=at position 0.5 with {\draw[black] (-3pt,-4pt) -- (-3pt,4pt);
                               \draw[black] (0pt,-4pt) -- (0pt,4pt);
                               \draw[black] (3pt,-4pt) -- (3pt,4pt);}}}},
}
\coordinate (O) at (0,0);
\draw (O) circle (2);
\fill (O) circle (1.5pt) node[right] {$O$};
\coordinate (A) at (-1.696,1.06);
\coordinate (B) at (0.877,1.798);
\coordinate (C) at (0.939,-1.766);
\coordinate (D) at (-1.658,-1.118);
\coordinate (E) at (-0.409,1.429);
\coordinate (F) at (-0.359,-1.442);
\node[above left] at (A) {$A$};
\node[above right] at (B) {$B$};
\node[below right] at (C) {$C$};
\node[below left] at (D) {$D$};
\node[above left] at (E) {$E$};
\node[below left] at (F) {$F$};
\draw[tickmark] (A) -- (B);
\draw[tickmark] (C) -- (D);
\draw (O) -- (E);
\draw (O) -- (F);
\node[above right, fill=white, inner sep=1pt] at (E) {$x$};
\draw (F) -- ($(F)!0.6!(O)$) node[midway, below left, fill=white, inner sep=1pt] {$5.4\text{ cm}$};
\coordinate (Ea) at ($(E)!0.3cm!(A)$);
\coordinate (Eb) at ($(E)!0.3cm!(O)$);
\draw (Ea) -- ($(Ea)+(Eb)-(E)$) -- (Eb);
\coordinate (Fa) at ($(F)!0.3cm!(C)$);
\coordinate (Fb) at ($(F)!0.3cm!(O)$);
\draw (Fa) -- ($(Fa)+(Fb)-(F)$) -- (Fb);
\end{tikzpicture}
[/tikz]

$OM \perp AB$ at $M$, and $AB = 14$ cm.
Find $AM$.
[tikz]\begin{tikzpicture}[every node/.style={font=\large}]
\usetikzlibrary{calc, angles, quotes}
\coordinate (O) at (0,0);
\draw (O) circle (2);
\fill (O) circle (1.5pt) node[below] {$O$};
\coordinate (A) at (-1.813,0.845);
\coordinate (B) at (1.813,0.845);
\coordinate (M) at (0,0.845);
\node[above left] at (A) {$A$};
\node[above right] at (B) {$B$};
\node[above] at (M) {$M$};
\draw (A) -- (M);
\draw (M) -- (B);
\node[above, inner sep=2pt] at (0,2.35) {$14\text{ cm}$};
\draw (O) -- (M);
\coordinate (Ma) at ($(M)!0.3cm!(A)$);
\coordinate (Mb) at ($(M)!0.3cm!(O)$);
\draw (Ma) -- ($(Ma)+(Mb)-(M)$) -- (Mb);
\end{tikzpicture}
[/tikz]

